// res/ENGINE_LICENSES (generated by scripts/build-engine.mjs) must keep a notice for every bundled package.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

const root = new URL('..', import.meta.url).pathname;
const text = readFileSync(`${root}res/ENGINE_LICENSES`, 'utf8');
const entries = text
  .split(`\n${'='.repeat(72)}\n`)
  .slice(1)
  .map((e) => e.replace(/^\s*Compiled into the plugin binary\n/, ''));

test('ENGINE_LICENSES names the known bundled packages and the compiled-in code', () => {
  for (const name of ['hydra-synth@', 'fraction.js@', '@strudel/core@', 'quickjs-ng', 'dr_libs'])
    assert.ok(text.includes(name), `${name} missing`);
});

test('every ENGINE_LICENSES entry has a heading and license text', () => {
  assert.ok(entries.length > 10);
  for (const e of entries) {
    const [head, ...body] = e.trim().split('\n');
    assert.match(head, /\S+ — \S/, `bad heading: ${head}`);
    assert.ok(body.join('').trim().length > 20, `no text for ${head}`);
  }
});
